pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address depositor) public {
        // Restrict amount to reasonable range for ether operations
        vm.assume(amount > 0);
        vm.assume(amount < 1e49); // Very large but still practical
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(c));

        // Record balance before deposit
        uint256 balBefore = depositor.balance;

        // Give depositor enough ether
        vm.deal(depositor, amount);

        // Deposit as the depositor
        vm.prank(depositor);
        c.Deposit{value: amount}();

        // After deposit, the contract's balance should equal the sum of deposited amounts
        // We can verify that the total ether sent to contract matches contract balance
        // Since only Deposit() adds ether, contract balance = sum of all msg.value
        // The bug breaks this because it doesn't track full msg.value in balances
        // The general invariant: for any single Deposit, the contract's ether balance
        // should increase by the full msg.value sent.
        // We check that the contract received exactly amount ether.
        // This is the universal property: address(c).balance >= amount (must be at least this deposit)
        // In reference, contract always receives exact msg.value.
        // In buggy, contract still receives msg.value but balances only increase by half,
        // so the accounting invariant that sum(balances) == address(c).balance is broken.
        assertTrue(address(c).balance >= amount);
    }
}

