import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, uint256 amount1, uint256 amount2) public {
        // admissible domain: caller isn't zero, amounts are nonzero and fit in a reasonable range
        vm.assume(caller != address(0));
        amount1 = bound(amount1, 1, type(uint128).max);
        amount2 = bound(amount2, 1, type(uint128).max);

