pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address origin, uint256 amount) public {
        // sender and origin must be different for the bug to potentially manifest
        vm.assume(sender != origin);
        // restrict amount to non-zero and avoid overflow in totalSum tracking (reasonable range)
        vm.assume(amount > 0 && amount <= type(uint128).max);
        // keep addresses away from precompiles and the contract itself
        vm.assume(sender != address(0) && origin != address(0));
        vm.assume(sender != address(c) && origin != address(c));

        uint256 totalSumBefore = c.balances(sender) + c.balances(origin);

        // simulate a call where msg.sender is 'sender' and tx.origin is 'origin'
        vm.deal(sender, amount);
        vm.prank(sender);
        // We start a prank that sets msg.sender = sender and tx.origin = origin
        vm.startPrank(sender, origin);
        c.Deposit{value: amount}();
        vm.stopPrank();

        uint256 totalSumAfter = c.balances(sender) + c.balances(origin);

        // Invariant: total balance of the two affected accounts increases exactly by the deposited amount
        assertTrue(totalSumAfter == totalSumBefore + amount);
    }
}

