import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        uint256 preBalance = c.balances(caller);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        uint256 postBalance = c.balances(caller);
