        vm.assume(_log != address(0));
        // Initialize the contract: set a min sum and mark initialized
        c.SetMinSum(_minSum);
        c.Initialized();
        // Record the Log address before calling SetLogFile
        address logBefore = address(c.Log());
        // 2. Drive the state through SetLogFile with the fuzzed non-zero address
        c.SetLogFile(_log);
        // 3. Assert that the Log address did not change after the call
        assertTrue(logBefore == address(c.Log()));
    }
}

