pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 exactBalance) public {
        // Restrict to admissible domain: balance must be at least MinSum (1 ether) and non-zero exactly.
        vm.assume(exactBalance >= 1 ether);
        vm.assume(exactBalance < type(uint256).max / 2); // prevent overflow on deposit

        // Setup: initialize, set up a user with a precise balance.
        c.Initialized();
        address user = address(0x1234);
        vm.deal(user, exactBalance);
        vm.prank(user);
        c.Deposit{value: exactBalance}();

        // Record balance before Collect attempt.
        uint256 beforeBalance = c.balances(user);

        // Attempt to collect exactly all of the balance.
        vm.prank(user);
        c.Collect(exactBalance);

        // Post-condition: balance must be zero.
        uint256 afterBalance = c.balances(user);
        assertTrue(afterBalance == 0);
    }
}
